function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('.elementor-price-list-item').each((_, el) => {
    const $item = $(el);

    // ---- name ----
    const $title = $item.find('.elementor-price-list-title');
    if (!$title.length) return;
    let name = cleanText($title.text());
    if (!name) return;
    // strip possible leading numbers like "12. "
    name = name.replace(/^\d+\s*[\.\-]\s*/, '').trim();

    // ---- price ----
    const $priceSpan = $item.find('.elementor-price-list-price');
    let price = null;
    if ($priceSpan.length) {
      price = parsePrice(cleanText($priceSpan.text()));
    }

    // ---- description ----
    const $desc = $item.find('.elementor-price-list-description');
    let description = null;
    if ($desc.length) {
      const d = cleanText($desc.text());
      description = d.length ? d : null;
    }

    // ---- section (heading) ----
    let section = null;
    const $section = $item.closest('.elementor-section');
    if ($section.length) {
      const $heading = $section.find('.elementor-heading-title').first();
      if ($heading.length) {
        let headingText = cleanText($heading.text());
        // remove any price that might be part of the heading (e.g., "Cocktails $17")
        headingText = headingText.replace(/\s*[€$£₤]\s*\d+[.,]?\d*\s*/g, '').trim();
        section = headingText;
      }
    }

    // ---- deduplication ----
    const key = (name.toLowerCase()) + '|' + (section || '');
    if (seen.has(key)) return;
    seen.add(key);

    items.push({
      section: section || null,
      name,
      description: description ?? null,
      price: price ?? null
    });
  });

  return items;
}
```

